do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero,markets,exchange,country) values ($q$BIDU$q$,$q$Baidu$q$,null,null,true,false,array[$q$US$q$,$q$HKEX$q$]::text[],$q$Nasdaq; HKEX 9888$q$,$q$CN$q$) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero, markets=case when cardinality(excluded.markets)>0 then excluded.markets else public.companies.markets end, exchange=coalesce(excluded.exchange, public.companies.exchange), country=coalesce(excluded.country, public.companies.country);
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Alibaba$q$,$q$public_company$q$),($q$Alibaba Cloud$q$,$q$public_company$q$),($q$Alphabet$q$,$q$public_company$q$),($q$AutoGo$q$,$q$private_company$q$),($q$Bilibili$q$,$q$public_company$q$),($q$BlackRock$q$,$q$public_company$q$),($q$ByteDance$q$,$q$private_company$q$),($q$China Mobile$q$,$q$public_company$q$),($q$China Telecom$q$,$q$public_company$q$),($q$China Unicom$q$,$q$public_company$q$),($q$Du Xiaoman$q$,$q$private_company$q$),($q$Geely$q$,$q$private_company$q$),($q$Handsome Reward Limited$q$,$q$private_company$q$),($q$Huawei$q$,$q$private_company$q$),($q$Integrity Partners V$q$,$q$private_company$q$),($q$JOYY$q$,$q$public_company$q$),($q$Kingsoft Cloud$q$,$q$public_company$q$),($q$Mango TV$q$,$q$public_company$q$),($q$Meta Platforms$q$,$q$public_company$q$),($q$Microsoft$q$,$q$public_company$q$),($q$PAG$q$,$q$private_company$q$),($q$PPStream$q$,$q$private_company$q$),($q$PostBus$q$,$q$organization$q$),($q$Tencent$q$,$q$public_company$q$),($q$Tencent Video$q$,$q$public_company$q$),($q$Trip$q$,$q$public_company$q$),($q$Trip.com$q$,$q$public_company$q$),($q$Uber$q$,$q$public_company$q$),($q$Volcano Engine$q$,$q$private_company$q$),($q$Xiaomi$q$,$q$public_company$q$),($q$YY Live$q$,$q$private_company$q$),($q$Youku$q$,$q$public_company$q$),($q$iQIYI$q$,$q$public_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$(3) Includes (i) 439,200,000 Class B ordinary shares held by Handsome Reward Limited, a British Virgin Islands company wholly owned and controlled by Mr. Robin Yanhong Li$q$),(2,$q$After negotiation with JOYY on next steps following the termination, Baidu (Hong Kong) Limited entered into new agreements on February 25, 2025 with JOYY to acquire, and acquired, YY Live for an aggregate price of approximately US$2.1 billion.$q$),(3,$q$After the divestiture, we hold  a non-controlling equity  interest in Du Xiaoman and have since then deconsolidated the financial results of Du Xiaoman from our consolidated financial statements in accordance with U.S. GAAP.$q$),(4,$q$As indicated in the accompanying Management’s Annual Report on Internal Control over Financial Reporting, management’s assessment of and conclusion on the effectiveness of internal control over financial reporting did not include the internal controls of YY Live that was acquired in 2025, which is included in the 2025 consolidated financial statements of the Company and constituted less than 1% of total assets as of December 31, 2025 and less than 3% of revenue for the year then ended.$q$),(5,$q$As of December 31, 2024 and 2025, the Group held approximately 7 % and  7 % equity interest in Trip, respectively, and the Group can actively participate in the operating and financing policies of Trip through its one seat on Trip’s board of directors with a total of eight members.$q$),(6,$q$Both loans will due on the date which PAG and its affiliates cease to hold any portion of the iQIYI PAG Convertible Notes (Note 15).$q$),(7,$q$Chinese internet companies, such as Alibaba, Tencent, ByteDance, and Xiaomi offer a broad range of online services, including search, feed, cloud services and smart devices, as well as foundation models and a diversified of AI native applications powered by foundation models.$q$),(8,$q$For example, we invested in Trip.com Group Limited.$q$),(9,$q$In August 2018, we completed the divestiture of Du Xiaoman, following which we recognized  our non-controlling equity  interest in Du Xiaoman as an equity method investment and Du Xiaoman became a related party.$q$),(10,$q$In August 2025, Apollo Go entered into a strategic partnership with Lyft, Inc. to deploy fully autonomous vehicles across key European markets through the Lyft platform, starting with Germany and the United Kingdom.$q$),(11,$q$In July 2025, Apollo Go entered into a multi-year strategic partnership with Uber Technologies, Inc. to deploy thousands of Apollo Go’s fully autonomous vehicles on the Uber platform across multiple international markets, with initial deployments planned for Asia and the Middle Ea$q$),(12,$q$In May 2013, we acquired the online video business of PPStream Inc. and merged it with iQIYI, and since then have consolidated its financial results into our consolidated financial statements.$q$),(13,$q$In November 2012, we obtained the controlling interest in iQIYI, Inc., or iQIYI, a prior equity method investee, and have since then consolidated its financial results into our consolidated financial statements.$q$),(14,$q$In October 2025, Apollo Go established a strategic partnership with PostBus, Switzerland’s leading public transport operator, to launch an  on-demand  autonomous mobility service.$q$),(15,$q$In the Middle East, Apollo Go officially launched fully autonomous ride-hailing services in Abu Dhabi with AutoGo, secured Dubai’s first fully driverless testing permit, and partnered with Uber to bring Apollo Go to the Uber platform in Dubai.$q$),(16,$q$Includes 128,640,168 Class A ordinary shares beneficially owned by BlackRock, Inc., over which BlackRock, Inc. has sole dispositive power, as of December 31, 2023.$q$),(17,$q$Jidu Auto is a joint venture that we established with Zhejiang Geely Holding Group (Geely).$q$),(18,$q$Management’s assessment of and conclusion on the effectiveness of internal control over financial reporting did not include the internal controls of YY Live that was acquired in 2025, which is included in our 2025 consolidated financial statements and constituted less than 1% of total assets as of December 31, 2025 and less than 3% of revenues for the year then ended.$q$),(19,$q$On February 25, 2025, Baidu (Hong Kong) Limited entered into new agreements with JOYY Inc and completed the acquisition of 100% equity interests in YY Live.$q$),(20,$q$On February 25, 2025, the Group entered into new agreements with JOYY Inc. and acquired 100 % equity interests in YY Live.$q$),(21,$q$Our servers are hosted at the internet data centers of major telecom operators, including China Telecom, China Unicom and China Mobile, in over ten selected cities across China.$q$),(22,$q$Subject to certain conditions, we may elect to deliver Trip.com Shares held by us in lieu of cash or a combination of cash and Trip.com Shares.$q$),(23,$q$The Group adopted a one-quarter lag in reporting for its share of equity earnings (losses) to Trip.$q$),(24,$q$The Group adopted a one-quarter lag in reporting for its share of equity earnings (losses) to a majority of equity method investees excluding Trip.$q$),(25,$q$The divestiture was completed in August 2018, following which we held a minority equity interest in Du Xiaoman, which was accounted for as an equity method investment.$q$),(26,$q$To our knowledge, Integrity Partners V, LLC holds 100,320 Class B ordinary shares of our company and was not a record shareholder of any Class A ordinary shares as at January 31, 2026.$q$),(27,$q$U.S.-based internet search providers and online marketing platforms, such as Microsoft, Google and Facebook, have a strong global presence, well established brand names, more users and customers and significantly greater financial resources than we do.$q$),(28,$q$We compete with Alibaba Cloud, Volcano Engine, Huawei and Kingsoft cloud for our cloud offerings.$q$),(29,$q$We rely heavily on China Telecommunications Corporation, China United Network Communications Group Company Limited, and China Mobile Communications Corporation to provide us with network services and data center hosting services.$q$),(30,$q$iQIYI faces competition for content sourcing, user traffic and advertising customers from other providers of online entertainment video services in Chinese mainland, primarily including Tencent Video, Youku, Mango TV and Bilibili.$q$),(31,$q$iQIYI, our controlled subsidiary listed on the Nasdaq Global Select Market, had experienced a working capital deficit as of December 31, 2023, 2024 and 2025.$q$),(32,$q$which mainly arose from the disposal of the Group’s partial interests in Trip$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$invests$q$,$q$BIDU$q$,$q$Trip.com$q$,$q${24,23,8,22,5}$q$::int[],$q${blk1,blk1,blk35,blk143,blk206}$q$::text[],null,null,null,null),(2,$q$acquires$q$,$q$BIDU$q$,$q$JOYY$q$,$q${2,20}$q$::int[],$q${blk23,blk205}$q$::text[],null,null,null,null),(3,$q$invests$q$,$q$BIDU$q$,$q$iQIYI$q$,$q${31,13}$q$::int[],$q${blk42,blk80}$q$::text[],null,null,null,null),(4,$q$invests$q$,$q$BIDU$q$,$q$Du Xiaoman$q$,$q${3,25,9}$q$::int[],$q${blk32,blk80,blk158}$q$::text[],null,null,null,null),(5,$q$supplies$q$,$q$China Telecom$q$,$q$BIDU$q$,$q${29,21}$q$::int[],$q${blk47-48,blk130}$q$::text[],null,null,null,null),(6,$q$supplies$q$,$q$China Unicom$q$,$q$BIDU$q$,$q${29,21}$q$::int[],$q${blk47-48,blk130}$q$::text[],null,null,null,null),(7,$q$supplies$q$,$q$China Mobile$q$,$q$BIDU$q$,$q${29,21}$q$::int[],$q${blk47-48,blk130}$q$::text[],null,null,null,null),(8,$q$acquires$q$,$q$BIDU$q$,$q$PPStream$q$,$q${12}$q$::int[],$q${blk80}$q$::text[],null,null,null,null),(9,$q$partners$q$,$q$BIDU$q$,$q$Uber$q$,$q${11}$q$::int[],$q${blk82}$q$::text[],null,null,null,null),(10,$q$partners$q$,$q$BIDU$q$,$q$Lyft$q$,$q${10}$q$::int[],$q${blk83}$q$::text[],null,null,null,null),(11,$q$partners$q$,$q$BIDU$q$,$q$PostBus$q$,$q${14}$q$::int[],$q${blk83}$q$::text[],null,null,null,null),(12,$q$partners$q$,$q$BIDU$q$,$q$AutoGo$q$,$q${15}$q$::int[],$q${blk82}$q$::text[],null,null,null,null),(13,$q$competes$q$,$q$BIDU$q$,$q$Alibaba$q$,$q${7}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(14,$q$competes$q$,$q$BIDU$q$,$q$Tencent$q$,$q${7}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(15,$q$competes$q$,$q$BIDU$q$,$q$ByteDance$q$,$q${7}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(16,$q$competes$q$,$q$BIDU$q$,$q$Xiaomi$q$,$q${7}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(17,$q$competes$q$,$q$BIDU$q$,$q$Microsoft$q$,$q${27}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(18,$q$competes$q$,$q$BIDU$q$,$q$Alphabet$q$,$q${27}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(19,$q$competes$q$,$q$BIDU$q$,$q$Meta Platforms$q$,$q${27}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(20,$q$competes$q$,$q$BIDU$q$,$q$Alibaba Cloud$q$,$q${28}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(21,$q$competes$q$,$q$BIDU$q$,$q$Volcano Engine$q$,$q${28}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(22,$q$competes$q$,$q$BIDU$q$,$q$Huawei$q$,$q${28}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(23,$q$competes$q$,$q$BIDU$q$,$q$Kingsoft Cloud$q$,$q${28}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(24,$q$competes$q$,$q$BIDU$q$,$q$Tencent Video$q$,$q${30}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(25,$q$competes$q$,$q$BIDU$q$,$q$Youku$q$,$q${30}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(26,$q$competes$q$,$q$BIDU$q$,$q$Mango TV$q$,$q${30}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(27,$q$competes$q$,$q$BIDU$q$,$q$Bilibili$q$,$q${30}$q$::int[],$q${blk90}$q$::text[],null,null,null,null),(28,$q$acquires$q$,$q$BIDU$q$,$q$YY Live$q$,$q${19,18,4}$q$::int[],$q${blk147,blk173,blk185}$q$::text[],100,$q$exact$q$,$q$ownership$q$,null),(29,$q$partners$q$,$q$BIDU$q$,$q$Geely$q$,$q${17}$q$::int[],$q${blk158}$q$::text[],null,null,null,null),(30,$q$invests$q$,$q$BlackRock$q$,$q$BIDU$q$,$q${16}$q$::int[],$q${blk156}$q$::text[],4.7,$q$exact$q$,$q$ownership$q$,null),(31,$q$invests$q$,$q$Handsome Reward Limited$q$,$q$BIDU$q$,$q${1}$q$::int[],$q${blk156}$q$::text[],16.5,$q$exact$q$,$q$ownership$q$,null),(32,$q$invests$q$,$q$Integrity Partners V$q$,$q$BIDU$q$,$q${26}$q$::int[],$q${blk157}$q$::text[],null,null,null,null),(33,$q$invests$q$,$q$PAG$q$,$q$iQIYI$q$,$q${6}$q$::int[],$q${blk1}$q$::text[],null,null,null,null),(34,$q$invests$q$,$q$BIDU$q$,$q$Trip$q$,$q${32}$q$::int[],$q${blk218}$q$::text[],null,null,null,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Lyft$q$ then ticker=$q$LYFT$q$ when $q$DoorDash$q$ then ticker=$q$DASH$q$ when $q$BIDU$q$ then ticker=$q$BIDU$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,cost_usd,status,review_status) values ('filings_extraction','batch',$q$BIDU FY2025 20-F (M15)$q$,'claude-sonnet-5-5 via Claude Code session',2.1024,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; isnew := false; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,trust_status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else $q$2025-12-31$q$::date end,$q$sec_filing$q$,$q$staged$q$,null,run_id,$q$2025-12-31$q$::date,r.note) returning id into rid; isnew := true; end if; if isnew then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1329099/000119312526109289/d38065d20f.htm$q$,r.sec[k],t,true,$q$2026-03-17$q$::date from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
